/// Returns true iff the three color counts can be arranged in a line
/// with no two adjacent items having the same color.
///
/// Feasibility criterion:
/// Let `max` be the maximum of (r, g, b) and `total = r + g + b`.
/// An arrangement exists exactly when `2 * max <= total + 1`.
pub fn check_lamp_arrangement(r: i8, g: i8, b: i8) -> bool {
    // Use a wider integer type to avoid any risk of overflow in arithmetic.
    let (r, g, b) = (r as i16, g as i16, b as i16);

    let max = r.max(g).max(b);
    let total = r + g + b;

    2 * max <= total + 1
}

